"use client";
import React, { useEffect, useState } from "react";
import { getCookie, hasCookie } from "cookies-next";
import getUserDetail from "@/services/auth/userDetail";
import Breadcrumb from "@/components/header/breadcrumb";
import Menu from "./menu";
import priceFormat from "@/helpers/priceFormat";
import Link from "next/link";
import Image from "next/image";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faCartShopping,
  faComments,
  faWallet,
} from "@fortawesome/free-solid-svg-icons";

export default function Page() {
  const [userLoading, setUserLoading] = useState(true);

  const [user, setUser] = useState({
    name: "",
    email: "",
  });
  const [userData, setUserData] = useState({
    name: "",
    firstName: "",
    lastName: "",
    email: "",
    avatar: "",
    currentPassword: "",
    newPassword: "",
    newPasswordAgain: "",
    countryId: "",
    travelStyles: [],
    lodgings: [],
    activities: [],
    categories: [],
    totalBooking: 0,
    totalEnquiry: 0,
    balance: 0,
    balanceCurrency: "",
    pendingCredit: 0,
  });

  const fetchUserDetail = async () => {
    const userData = await getUserDetail({ token: getCookie("auth-token") });
    return userData;
  };

  useEffect(() => {
    if (hasCookie("auth-token")) {
      try {
        fetchUserDetail().then((res: any) => {
          setUserData({
            name: res.name,
            firstName: res.first_name,
            lastName: res.last_name,
            email: res.email,
            currentPassword: "",
            newPassword: "",
            avatar: res.avatar,
            newPasswordAgain: "",
            countryId: res.country_id,
            travelStyles: res.meta.preffered_travel_styles,
            lodgings: res.meta.preffer_lodgings,
            activities: res.meta.activities,
            categories: res.meta.categories,
            totalBooking: res.total_booking,
            totalEnquiry: res.total_enquiry,
            balance: res.balance,
            balanceCurrency: res.balance_currency,
            pendingCredit: res.pending_credit,
          });
          setUser({ name: res.first_name + " " + res.last_name, email: res.email });
          setUserLoading(false);
        });
      } catch (e) {}
    } else {
      setUserLoading(false);
    }
  }, []);

  const showProfile = !!getCookie("user-role");

  const stats = [
    {
      href: "/profile/bookings-enquiries?list=booking",
      icon: faCartShopping,
      value: `${userData.totalBooking} ${userData.totalBooking > 1 ? "Bookings" : "Booking"}`,
    },
    {
      href: "/profile/bookings-enquiries?list=enquiry",
      icon: faComments,
      value: `${userData.totalEnquiry} ${userData.totalEnquiry > 1 ? "Enquiries" : "Enquiry"}`,
    },
  ];

  return (
    <main className="tw-font-display">
      <div className="tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6">
        <Breadcrumb items={[]} />
        <h1 className="tw-mt-2 tw-mb-5 tw-text-[clamp(22px,2.6vw,30px)] tw-font-bold tw-tracking-tight tw-text-[#14101c]">
          Profile
        </h1>

        <div className="tw-grid tw-grid-cols-1 tw-gap-6 md:tw-grid-cols-[260px_minmax(0,1fr)]">
          <div>
            <Menu />
          </div>

          <div>
            {userLoading && (
              <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 tw-py-16 tw-text-[#5d556c]">
                <span className="tw-inline-block tw-h-8 tw-w-8 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
                <p className="tw-m-0 tw-text-sm">Loading. Please wait.</p>
              </div>
            )}

            {!userLoading && (
              <div className="tw-overflow-hidden tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-shadow-[0_8px_30px_rgba(20,16,28,0.05)]">
                {/* Static header band */}
                <div className="tw-h-28 tw-bg-gradient-to-r tw-from-[#854ec9] tw-to-[#6a3da4] sm:tw-h-32" />

                {/* Identity row */}
                {showProfile && (
                  <div className="tw-relative tw-z-10 tw-flex tw-items-end tw-gap-4 tw-px-6 tw-pb-6">
                    <div className="tw--mt-16 tw-shrink-0">
                      <Image
                        src={userData.avatar || "/images/avatar-2.png"}
                        alt="Profile Picture"
                        width={110}
                        height={110}
                        quality={100}
                        className="tw-h-[110px] tw-w-[110px] tw-rounded-full tw-bg-white tw-object-cover tw-ring-4 tw-ring-white tw-shadow-[0_10px_30px_rgba(20,16,28,0.18)]"
                      />
                    </div>
                    <div className="tw-pb-1">
                      <h2 className="tw-m-0 tw-text-xl tw-font-bold tw-tracking-tight tw-text-[#14101c]">
                        {user.name}
                      </h2>
                      {user.email && (
                        <p className="tw-m-0 tw-text-sm tw-text-[#6b6577]">{user.email}</p>
                      )}
                    </div>
                  </div>
                )}
              </div>
            )}

            {!userLoading && (
              <div className="tw-mt-5 tw-grid tw-grid-cols-1 tw-gap-4 sm:tw-grid-cols-3">
                {stats.map((s) => (
                  <Link
                    key={s.href}
                    href={s.href}
                    className="tw-group tw-flex tw-flex-col tw-items-center tw-gap-3 tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-6 tw-text-center tw-no-underline tw-transition-all tw-duration-300 hover:tw--translate-y-1 hover:tw-shadow-[0_14px_34px_rgba(20,16,28,0.12)]"
                  >
                    <span className="tw-flex tw-h-14 tw-w-14 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#f4eefc] tw-text-[#854ec9] tw-transition-colors group-hover:tw-bg-[#854ec9] group-hover:tw-text-white">
                      <FontAwesomeIcon icon={s.icon} className="tw-text-xl" />
                    </span>
                    <span className="tw-text-lg tw-font-bold tw-text-[#14101c]">{s.value}</span>
                  </Link>
                ))}

                <Link
                  href="/profile/credit-details"
                  className="tw-group tw-flex tw-flex-col tw-items-center tw-gap-3 tw-rounded-2xl tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-white tw-p-6 tw-text-center tw-no-underline tw-transition-all tw-duration-300 hover:tw--translate-y-1 hover:tw-shadow-[0_14px_34px_rgba(20,16,28,0.12)]"
                >
                  <span className="tw-flex tw-h-14 tw-w-14 tw-items-center tw-justify-center tw-rounded-full tw-bg-[#f4eefc] tw-text-[#854ec9] tw-transition-colors group-hover:tw-bg-[#854ec9] group-hover:tw-text-white">
                    <FontAwesomeIcon icon={faWallet} className="tw-text-xl" />
                  </span>
                  <span className="tw-text-lg tw-font-bold tw-text-[#14101c]">
                    {priceFormat({
                      amount: userData.balance,
                      currency: userData.balanceCurrency,
                    })}{" "}
                    Credit{" "}
                    {userData.pendingCredit > 0 && (
                      <small className="tw-block tw-text-xs tw-font-medium tw-text-[#b23838]">
                        (
                        {priceFormat({
                          amount: userData.pendingCredit,
                          currency: userData.balanceCurrency,
                        })}{" "}
                        Pending)
                      </small>
                    )}
                  </span>
                </Link>
              </div>
            )}
          </div>
        </div>
      </div>
    </main>
  );
}
